body.script:
const MODE     = '';
const SAVE_URL = '';
const CSRF     = '';
let tables  = ;
let waiters = ;

let selectedId = null;
let dragState  = null;

// ── Boot ──────────────────────────────────────────────────────────────────
window.addEventListener('DOMContentLoaded', () => {
    if (MODE === 'hall') {
        document.getElementById('seatedCard').style.display = 'none';
        document.getElementById('occCard').style.display    = 'none';
    }
    render();
});

// ── Render ────────────────────────────────────────────────────────────────
function render() { renderCanvas(); renderSidebar(); updateStats(); }

function getStatus(t) {
    if (MODE === 'hall') return 'layout';
    if (t.vip) return 'vip';
    const pct = t.capacity ? (t.guests / t.capacity) * 100 : 0;
    return pct === 0 ? 'free' : pct <= 60 ? 'partial' : pct <= 100 ? 'full' : 'over';
}

function renderCanvas() {
    document.querySelectorAll('.tnode').forEach(n => n.remove());
    const canvas = document.getElementById('canvas');
    tables.forEach(t => {
        const isRect = (t.shape === 'rect' || t.shape === 'rectangular');
        const w = isRect ? 116 : 86;
        const h = isRect ? 66  : 86;
        const status = getStatus(t);
        const shapeClass = 's-' + (isRect ? 'rect' : (t.shape || 'round'));

        const node = document.createElement('div');
        node.className = 'tnode' + (selectedId === t.id ? ' sel' : '');
        node.dataset.id = t.id;
        node.style.cssText = `left:${t.x}%;top:${t.y}%;transform:translate(-50%,-50%);`;

        let inner = (t.vip ? '<div class="crown">★</div>' : '') +
            `<div class="tshape ${shapeClass} st-${status}" style="width:${w}px;height:${h}px;">` +
                `<div class="tlabel">${esc(t.name)}</div>`;
        if (MODE === 'hall') {
            inner += `<div class="tsub">${t.capacity} seats</div>`;
        } else {
            inner += `<div class="tsub">${t.guests}/${t.capacity}</div>` +
                     `<div class="tsub" style="font-size:8px;">${t.waiter ? t.waiter.split(' ')[0] : ''}</div>`;
        }
        inner += '</div>';
        node.innerHTML = inner;

        node.addEventListener('mousedown', startDrag);
        node.addEventListener('click', () => { if (!dragState || !dragState.moved) openDetail(t.id); });
        canvas.appendChild(node);
    });
}

function renderSidebar() {
    const list = document.getElementById('tableList');
    list.innerHTML = '';
    if (!tables.length) {
        list.innerHTML = '<div style="color:var(--muted);font-size:11px;">No tables.</div>';
        return;
    }
    tables.forEach(t => {
        let bc = 'b-layout', bl = t.shape || 'round';
        if (MODE === 'wedding') {
            const pct = t.capacity ? (t.guests / t.capacity) * 100 : 0;
            if (t.vip)            { bc = 'b-vip';    bl = '★ VIP'; }
            else if (pct === 0)   { bc = 'b-free';   bl = 'Free'; }
            else if (pct <= 60){ bc = 'b-partial'; bl = 'Partial'; }
            else if (pct <= 100){ bc = 'b-full';  bl = 'Full'; }
            else                  { bc = 'b-over';   bl = 'Over!'; }
        }
        const item = document.createElement('div');
        item.className = 'tli' + (selectedId === t.id ? ' sel' : '') + (t.vip ? ' vip' : '');
        const sub = MODE === 'hall'
            ? t.capacity + ' seats · ' + (t.shape || 'round')
            : t.guests + '/' + t.capacity + ' · ' + (t.waiter || 'No waiter');
        item.innerHTML = `<div class="tli-info">
            <div class="tli-name">${esc(t.name)}</div>
            <div class="tli-sub">${sub}</div>
          </div><span class="tbadge ${bc}">${bl}</span>`;
        item.addEventListener('click', () => openDetail(t.id));
        list.appendChild(item);
    });
}

function updateStats() {
    const cap    = tables.reduce((s, t) => s + (t.capacity || 0), 0);
    const seated = tables.reduce((s, t) => s + (t.guests   || 0), 0);
    const occ    = cap ? Math.round(seated / cap * 100) : 0;
    document.getElementById('statTables').textContent = tables.length;
    document.getElementById('statCap').textContent    = cap;
    document.getElementById('statSeated').textContent = seated;
    document.getElementById('statOcc').textContent    = MODE === 'hall' ? '—' : occ + '%';
}

// ── Drag ──────────────────────────────────────────────────────────────────
function startDrag(e) {
    if (e.button !== 0) return;
    e.preventDefault();
    const id   = e.currentTarget.dataset.id;
    const t    = tables.find(x => x.id === id);
    if (!t) return;
    const rect = document.getElementById('canvas').getBoundingClientRect();
    dragState = { id, startX:e.clientX, startY:e.clientY, origX:t.x, origY:t.y, rect, moved:false };
    window.addEventListener('mousemove', onDrag);
    window.addEventListener('mouseup',   endDrag);
}
function onDrag(e) {
    if (!dragState) return;
    const dx = e.clientX - dragState.startX;
    const dy = e.clientY - dragState.startY;
    if (Math.abs(dx) + Math.abs(dy) > 4) dragState.moved = true;
    if (!dragState.moved) return;
    const t = tables.find(x => x.id === dragState.id);
    if (!t) return;
    t.x = Math.max(5, Math.min(95, dragState.origX + (dx / dragState.rect.width)  * 100));
    t.y = Math.max(15, Math.min(92, dragState.origY + (dy / dragState.rect.height) * 100));
    const node = document.querySelector(`.tnode[data-id="${dragState.id}"]`);
    if (node) { node.style.left = t.x + '%'; node.style.top = t.y + '%'; }
}
function endDrag() {
    window.removeEventListener('mousemove', onDrag);
    window.removeEventListener('mouseup',   endDrag);
    setTimeout(() => { dragState = null; }, 50);
}

// ── Detail Panel ──────────────────────────────────────────────────────────
function openDetail(id) {
    selectedId = id;
    const t = tables.find(x => x.id === id);
    if (!t) return;

    document.getElementById('detTitle').textContent = t.name;
    const body = document.getElementById('detBody');

    if (MODE === 'hall') {
        // Hall mode: only rename and capacity
        body.innerHTML = `
          <div class="frow"><div class="flbl">Table Name</div>
            <input class="finput" id="dName" value="${esc(t.name)}"/></div>
          <div class="frow"><div class="flbl">Shape</div>
            <select class="fselect" id="dShape">
              ${['round','rect','square','oval'].map(s =>
                `<option value="${s}" ${t.shape===s?'selected':''}>${s}</option>`).join('')}
            </select></div>
          <div class="frow"><div class="flbl">Capacity (seats)</div>
            <input class="finput" type="number" id="dCap" value="${t.capacity}" min="1" max="50"/></div>
        `;
    } else {
        // Wedding mode: guests, waiter, vip, notes
        const pct = t.capacity ? Math.min(t.guests / t.capacity * 100, 150) : 0;
        const barColor = pct === 0 ? 'var(--success)' : pct <= 60 ? 'var(--gold)' : pct <= 100 ? 'var(--accent)' : 'var(--danger)';
        const waiterOpts = '<option value="0">— No Waiter —</option>' +
            waiters.map(w => `<option value="${w.id}" ${t.waiter_id===w.id?'selected':''}>${esc(w.name)}</option>`).join('');
        body.innerHTML = `
          <div class="frow"><div class="flbl">Table · Shape · Cap.</div>
            <div class="fval">${esc(t.name)} · ${t.shape} · ${t.capacity} seats</div></div>
          <div class="frow"><div class="flbl">Guests to Seat</div>
            <input class="finput" type="number" id="dGuests" value="${t.guests}" min="0" oninput="liveOcc(this.value)"/>
            <div class="occ-wrap"><div class="occ-bar" id="occBar" style="width:${Math.min(pct,100)}%;background:${barColor}"/></div>
            <div id="occPct" style="font-size:10px;color:var(--muted);margin-top:2px;">${Math.round(pct)}% occupancy</div></div>
          <div class="frow"><div class="flbl">Assigned Waiter</div>
            <select class="fselect" id="dWaiter">${waiterOpts}</select></div>
          <div class="frow"><div class="flbl">VIP Table</div>
            <label style="display:flex;align-items:center;gap:7px;cursor:pointer;">
              <input type="checkbox" id="dVip" ${t.vip?'checked':''} onchange="toggleVip()"/>
              <span style="font-size:13px;">VIP ★</span></label></div>
          <div class="frow"><div class="flbl">Special Notes</div>
            <input class="finput" id="dNotes" value="${esc(t.notes||'')}"/></div>
        `;
    }

    document.getElementById('detailPanel').classList.add('open');
    renderSidebar();
    renderCanvas();
}

function closeDetail() {
    selectedId = null;
    document.getElementById('detailPanel').classList.remove('open');
    render();
}

function liveOcc(val) {
    const t = tables.find(x => x.id === selectedId);
    if (!t) return;
    const pct = t.capacity ? Math.min((parseInt(val)||0) / t.capacity * 100, 150) : 0;
    const bar = document.getElementById('occBar');
    if (bar) {
        bar.style.width = Math.min(pct, 100) + '%';
        bar.style.background = pct === 0 ? 'var(--success)' : pct <= 60 ? 'var(--gold)' : pct <= 100 ? 'var(--accent)' : 'var(--danger)';
        document.getElementById('occPct').textContent = Math.round(pct) + '% occupancy';
    }
}

function toggleVip() {
    const t = tables.find(x => x.id === selectedId);
    const cb = document.getElementById('dVip');
    if (t && cb) { t.vip = cb.checked; renderCanvas(); renderSidebar(); }
}

function applyDetail() {
    const t = tables.find(x => x.id === selectedId);
    if (!t) return;
    if (MODE === 'hall') {
        t.name     = (document.getElementById('dName')?.value || t.name).trim();
        t.shape    = document.getElementById('dShape')?.value || t.shape;
        t.capacity = parseInt(document.getElementById('dCap')?.value) || t.capacity;
    } else {
        t.guests    = parseInt(document.getElementById('dGuests')?.value) || 0;
        const sel   = document.getElementById('dWaiter');
        t.waiter_id = parseInt(sel?.value) || 0;
        t.waiter    = sel?.selectedOptions[0]?.text || '';
        if (t.waiter === '— No Waiter —') t.waiter = '';
        t.vip       = document.getElementById('dVip')?.checked || false;
        t.notes     = document.getElementById('dNotes')?.value || '';
    }
    render();
    toast('Changes applied', 'success');
}

function applyAndClose() { applyDetail(); closeDetail(); }

// ── Save to Odoo ──────────────────────────────────────────────────────────
async function savePlan() {
    const payload = tables.map(t => ({
        phys_id:       t.phys_id || 0,
        assignment_id: t.assignment_id || 0,
        name:          t.name,
        shape:         t.shape,
        capacity:      t.capacity,
        guests:        t.guests    || 0,
        waiter_id:     t.waiter_id || 0,
        vip:           t.vip       || false,
        notes:         t.notes     || '',
        x:             Math.round(t.x),
        y:             Math.round(t.y),
    }));
    try {
        const res = await fetch(SAVE_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-CSRFToken': CSRF },
            body: JSON.stringify({ jsonrpc:'2.0', method:'call', id:1, params:{ tables: payload } }),
        });
        const data = await res.json();
        if (data.result && data.result.success) {
            toast('Saved to Odoo ✓', 'success');
        } else {
            toast('Error: ' + (data.result?.error || JSON.stringify(data.error)), 'error');
        }
    } catch(err) {
        toast('Network error: ' + err.message, 'error');
    }
}

function resetLayout() {
    if (!confirm('Reset all positions to a default grid?')) return;
    tables.forEach((t, i) => {
        t.x = 12 + ((i % 5) * 17);
        t.y = 38 + (Math.floor(i / 5) * 24);
    });
    render();
    toast('Layout reset', 'info');
}

// ── Utils ─────────────────────────────────────────────────────────────────
function esc(s) {
    return String(s)
        .replace(/&/g,'&amp;')
        .replace(/</g,'&lt;')
        .replace(/>/g,'&gt;')
        .replace(/"/g,'&quot;');
}

let toastTimer;
function toast(msg, type='info') {
    const el = document.getElementById('toast');
    document.getElementById('toastIcon').textContent = {success:'✓',error:'✗',info:'ℹ'}[type]||'ℹ';
    document.getElementById('toastMsg').textContent  = msg;
    el.className = 'toast ' + type + ' show';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('show'), 3000);
}
